Drupal.behaviors.displayColorDefinitions={attach(){function e(e){return`0${parseInt(e,10).toString(16)}`.slice(-2)}function t(t){let n=t.match(/^rgb\((\d+),\s*(\d+),\s*(\d+)\)$/);return`#${e(n[1])}${e(n[2])}${e(n[3])}`}let n=document.querySelectorAll(`.cl-colors__item`);n&&n.forEach(e=>{let n=window.getComputedStyle(e.querySelector(`.cl-colors__swatch`),null).getPropertyValue(`background-color`),r=e.querySelector(`.cl-colors__definition`);r.textContent=t(n)})}};